"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["86916"],{40368(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formatos_permitidos.formato_duplicado","status":422,"titulo":"O mesmo formato aparece mais de uma vez na lista"},"descricao":{"codigo":"uniplus.selecao.formatos_permitidos.formato_duplicado","requisitos":[],"oQueAconteceu":["Cada formato aceito por uma exig\xeancia aparece uma vez na lista, com o seu limite de tamanho\\npr\xf3prio, se houver. A lista enviada repete um formato. A mensagem de detalhe identifica o formato\\nrepetido.","A confer\xeancia acontece na montagem de cada exig\xeancia, depois das confer\xeancias do tipo de\\ndocumento, das condi\xe7\xf5es e das bases legais, e depois da idade m\xe1xima de emiss\xe3o; a do modelo\\ncitado vem em seguida. A confer\xeancia registra as recusas das regras informadas, e a lista de\\nformatos para na primeira entrada com defeito. Em cada entrada, o formato desconhecido\\n([`formato_invalido`](/erros/uniplus.selecao.formatos_permitidos.formato_invalido)) \xe9 conferido\\nantes da repeti\xe7\xe3o, e o limite por formato\\n([`tamanho_maximo_bytes_max_invalido`](/erros/uniplus.selecao.formatos_permitidos.tamanho_maximo_bytes_max_invalido))\\ndepois dela.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz formato repetido, porque a\\ndefini\xe7\xe3o o recusa antes. Nessas leituras a recusa se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido\\nenviado."],"comoResolver":["Deixe cada formato uma s\xf3 vez na lista. Se os dois itens tinham limites de tamanho diferentes, fique\\ncom o limite que deve valer para o formato. Depois, envie a defini\xe7\xe3o de novo.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir os documentos exigidos do\\nprocesso n\xe3o a corrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Consulta do formul\xe1rio renderiz\xe1vel do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formatos permitidos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);